<script>(function(){var r=document.documentElement,k='queue-monitor-theme',a=['light','dark','system'];function s(){return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}function read(){try{var v=localStorage.getItem(k);return a.includes(v)?v:'system'}catch(e){return 'system'}}var p=read();function apply(){var v=p==='system'?s():p;r.dataset.theme=v;r.style.colorScheme=v}function mount(){apply();if(document.getElementById('queue-monitor-theme-picker'))return;var w=document.createElement('label');w.id='queue-monitor-theme-picker';w.innerHTML='<span>◐</span><select aria-label="Theme"><option value="light">Day</option><option value="dark">Night</option><option value="system">System</option></select>';var x=w.querySelector('select');x.value=p;x.onchange=function(){p=x.value;try{localStorage.setItem(k,p)}catch(e){}apply()};document.body.appendChild(w)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();var m=matchMedia('(prefers-color-scheme: dark)');m.addEventListener?m.addEventListener('change',function(){if(p==='system')apply()}):m.addListener(function(){if(p==='system')apply()})})();</script>